        if (r["listProcsStatCd"] === '30') { if (typeof scwin.viewDetail === 'function') { await scwin.viewDetail(r["bzProcsNo"], r["seq"]); } else { console.error('[sdd] 행 동작 미정의: scwin.viewDetail (열 작성중)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.viewDetail'); } return; }
        if (r["listProcsStatCd"] === '35') { if (typeof scwin.viewDetail === 'function') { await scwin.viewDetail(r["bzProcsNo"], r["seq"]); } else { console.error('[sdd] 행 동작 미정의: scwin.viewDetail (열 수정가능)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.viewDetail'); } return; }
        if (r["listProcsStatCd"] === '37') { if (typeof scwin.viewDetail === 'function') { await scwin.viewDetail(r["bzProcsNo"], r["seq"]); } else { console.error('[sdd] 행 동작 미정의: scwin.viewDetail (열 재작성)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.viewDetail'); } return; }
        if (typeof scwin.viewDetail === 'function') { await scwin.viewDetail(r["bzProcsNo"], r["seq"]); } else { console.error('[sdd] 행 동작 미정의: scwin.viewDetail (열 ())'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.viewDetail'); } return;
